/-- The set of level-`q` tuples actually achieved by some `f ∈ F`. As a
subtype of the finite `LevelTuple`, it is a `Fintype`; its cardinality is
`Nq q`. -/
def AchievedTuple (cov : (p : ℕ) → BracketingCoverData F (scale p) P)
    (q₀ q : ℕ) : Type _ :=
  {t : LevelTuple cov q₀ q // ∃ f, ∃ hf : f ∈ F, assignTuple cov q₀ q hf = t}

noncomputable def conditionalProjectedRademacherSup
    {Ω : Type*} {F : Set (Ω → ℝ)} {Φ : Ω → ℝ}
    {n L : ℕ} {X : Fin n → Ω}
    (B : FiniteEmpiricalDyadicNets F Φ n X L)
    (q : ℕ) : ℝ≥0∞ :=
  conditionalRademacherSup (Set.range (B.proj q)) n X

def head {Ω : Type*} {F : Set (Ω → ℝ)} {Φ : Ω → ℝ}
    {n L : ℕ} {X : Fin n → Ω}
    (B : FiniteEmpiricalDyadicNets F Φ n X L)
    (f : F) : Ω → ℝ :=
  B.proj 0 f

theorem head_mem {Ω : Type*} {F : Set (Ω → ℝ)} {Φ : Ω → ℝ}
    {n L : ℕ} {X : Fin n → Ω}
    (B : FiniteEmpiricalDyadicNets F Φ n X L) (f : F) :
    B.head f ∈ B.net 0 := by
  exact B.proj_mem 0 (Nat.zero_le L) f

def link {Ω : Type*} {F : Set (Ω → ℝ)} {Φ : Ω → ℝ}
    {n L : ℕ} {X : Fin n → Ω}
    (B : FiniteEmpiricalDyadicNets F Φ n X L)
    (q : ℕ) (f : F) : Ω → ℝ :=
  B.proj (q + 1) f - B.proj q f

noncomputable def projectedRademacherSup
    {Ω : Type*} {F : Set (Ω → ℝ)} {Φ : Ω → ℝ}
    {n L : ℕ} {X : Fin n → Ω}
    (B : FiniteEmpiricalDyadicNets F Φ n X L)
    (q : ℕ) (ε : Fin n → Bool) : ℝ≥0∞ :=
  rademacherSup (Set.range (B.proj q)) n X ε

lemma IsEnvelope.mono {F F' : Set (Ω → ℝ)} {G : Ω → ℝ}
    (hG : IsEnvelope F G) (hF' : F' ⊆ F) : IsEnvelope F' G :=
  fun f hf x => hG f (hF' hf) x

lemma IsEnvelope.nonneg {F : Set (Ω → ℝ)} {G : Ω → ℝ}
    (hG : IsEnvelope F G) {f : Ω → ℝ} (hf : f ∈ F) (x : Ω) : 0 ≤ G x :=
  (abs_nonneg (f x)).trans (hG f hf x)

/-- The centred member of `F` packaged as an element of `L²(P)`. -/
def centredLp (f : ↥F) : Lp ℝ 2 P :=
  (memLp_centred hF_env hF_meas f.2).toLp _

/-- The **projection truncation** of `g` at level `M`: clamp each value into
`[−M, M]`. -/
def clampFn (M : ℝ) (g : Ω → ℝ) : Ω → ℝ := fun x => clampReal M (g x)

noncomputable def conditionalRademacherSup {Ω : Type*}
    (F : Set (Ω → ℝ)) (n : ℕ) (X : Fin n → Ω) : ℝ≥0∞ :=
  ∫⁻ ε, rademacherSup F n X ε ∂rademacherCube n

