/-- Flip every coordinate of a Boolean Rademacher vector. -/
def rademacherFlipAll {n : ℕ}
    (ε : Fin n → Bool) : Fin n → Bool := fun j => !(ε j)

/-- A Rademacher sign, with the convention `false ↦ 1` and `true ↦ -1`. -/
def rademacherSign (b : Bool) : ℝ :=
  if b then -1 else 1

/-- **Polynomial growth of the loss** (vdV p. 147): `ℓ(h) ≤ 1 + ‖h‖ᵖ`. -/
def PolyGrowthLoss (p : ℝ) (ℓ : EuclideanSpace ℝ (Fin k) → ℝ≥0∞) : Prop :=
  ∀ h, ℓ h ≤ ENNReal.ofReal (1 + ‖h‖ ^ p)

/-- The first-`n`-observations statistic on the joint space. -/
def doobData (n : ℕ) (ω : (ℕ → 𝓧) × Θ) : Fin n → 𝓧 :=
  fun i => ω.1 i.val

