/-- The open **corner simplex**: the first `k` category probabilities, positive with sum `< 1`
(Gelman §3.4, in the corner parametrization). -/
def simplexCorner (k : ℕ) : Set (Fin k → ℝ) :=
  {θ | (∀ i, 0 < θ i) ∧ ∑ i, θ i < 1}

/-- **Ignorability for a single arm** `Y(z) ⫫ Z | X` (Ding Assumption 10.1). -/
def Ignorable (μ : Measure Ω) (Z : Ω → Bool) (y : Ω → ℝ) (X : Ω → 𝒳) : Prop :=
  ∀ x : 𝒳, IndepFun y Z (μ[|cell X x])

/-- The **observed outcome vector** `Yᵢ = ZᵢYᵢ(1) + (1 - Zᵢ)Yᵢ(0)` (Ding eq. (2.2)). -/
def observed (S : ScienceTable n) (z : Assignment n) : Fin n → ℝ :=
  fun i => if z i then S.y1 i else S.y0 i

/-- The **arm cell** `{Z = z, X = x}`. -/
def armCell (Z : Ω → Bool) (X : Ω → 𝒳) (z : Bool) (x : 𝒳) : Set Ω :=
  {ω | Z ω = z} ∩ X ⁻¹' {x}

/-- The set of units in arm `a` under assignment `z` (`a = true`: treated). -/
def armIdx (z : Assignment n) (a : Bool) : Finset (Fin n) :=
  Finset.univ.filter fun i => z i = a

/-- The map from an `n₁`-subset of units to the assignment vector treating exactly that
subset. -/
def ofSubset (s : SubsetsOfCard n n₁) : Assignment n := fun i => decide (i ∈ s.val)

/-- The **level set of the propensity score**: the units whose covariate cell has
propensity `v`. A finite union of covariate cells. -/
def propensityLevel (μ : Measure Ω) (Z : Ω → Bool) (X : Ω → 𝒳) (v : ℝ) : Set Ω :=
  {ω | propensity μ Z X (X ω) = v}

/-- The set of units in stratum `k`. -/
def stratum (g : Fin n → Fin K) (k : Fin K) : Finset (Fin n) :=
  Finset.univ.filter fun i => g i = k

/-- The **retained (trimmed) population**: the units whose covariate cell has propensity
score in `[η, 1 - η]` (Ding §11.2.3, Assumption 20.1). -/
def trimmedSet (μ : Measure Ω) (Z : Ω → Bool) (X : Ω → 𝒳) (η : ℝ) : Set Ω :=
  {ω | η ≤ propensity μ Z X (X ω) ∧ propensity μ Z X (X ω) ≤ 1 - η}

/-- The **acceptance region** of Algorithm 2.1 (ECS §2.1): the pairs `(y, u)`
with `u·c·q(y) ≤ p(y)`.  Multiplicative form of the book's `u ≤ p(y)/(c·q(y))`;
the two agree wherever `q y ≠ 0`, hence `Q`-a.e. -/
def rejectionAccept (p q : 𝓧 → ℝ≥0∞) (c : ℝ≥0∞) : Set (𝓧 × ℝ) :=
  {yu | ENNReal.ofReal yu.2 * (c * q yu.1) ≤ p yu.1}

