    0 < n → 0 < d → 0 < κ → 0 < R → 0 < δ → δ < 1 → 0 < M.B → 0 < C → M.θstar ∈ StatLean.HighDimensionalStatistics.MEstimator.suppSubmodule S → ∀ (τSq : ℝ), 0 ≤ τSq → (∀ (ω : Ω), StatLean.HighDimensionalStatistics.MEstimator.RSC (StatLean.HighDimensionalStatistics.MEstimator.glmCost M ω) M.θstar (StatLean.HighDimensionalStatistics.MEstimator.l1Seminorm d) κ R τSq) → τSq * ↑S.card ≤ κ / 128 → 144 * (lam ^ 2 / κ ^ 2) * ↑S.card ≤ R ^ 2 → lam = 4 * M.B * C * (√(Real.log ↑d / ↑n) + δ) → (∀ (ω : Ω) (θ : EuclideanSpace ℝ (Fin d)), StatLean.HighDimensionalStatistics.MEstimator.glmCost M ω (θhat ω) + lam * StatLean.HighDimensionalStatistics.l1Norm (θhat ω) ≤ StatLean.HighDimensionalStatistics.MEstimator.glmCost M ω θ + lam * StatLean.HighDimensionalStatistics.l1Norm θ) → ENNReal.ofReal (1 - 2 * Real.exp (-2 * ↑n * δ ^ 2)) ≤ μ {ω | ‖θhat ω - M.θstar‖ ^ 2 ≤ 144 * (lam ^ 2 / κ ^ 2) * ↑S.card ∧ StatLean.HighDimensionalStatistics.l1Norm (θhat ω - M.θstar) ≤ 48 * (lam / κ) * ↑S.card}

