entries.source:
/-- The linear predictor `ηᵢ(θ) = ⟨xᵢ, θ⟩ = ∑ⱼ Xᵢⱼ·θⱼ` (the `i`-th coordinate of `Xθ`). -/
def linPred (X : Matrix (Fin n) (Fin d) ℝ) (θ : EuclideanSpace ℝ (Fin d)) (i : Fin n) : ℝ :=
  ∑ j, X i j * θ.ofLp j

/-- The `j`-th **column** `X_j` of the design matrix, as a vector in `E^n`. -/
def col (X : Matrix (Fin n) (Fin d) ℝ) (j : Fin d) : EuclideanSpace ℝ (Fin n) :=
  WithLp.toLp 2 (fun i => X i j)

entries.doc:
**Matrix ℓ∞ operator norm** `|||A|||_∞ = max_i ∑_j |A i j|` (max absolute row sum);
the matrix norm appearing in Wainwright's bound (7.45). Equals Mathlib's
`Matrix.linfty_opNorm`. For an empty row index it is `0`.

entries.source:
/-- The **restricted cone** `C_α(S) = {Δ : ‖Δ_{Sᶜ}‖₁ ≤ α ‖Δ_S‖₁}` (Lu-BDA §10.1,
Definition 10.1 (Restricted Eigenvalue)):
deviations whose mass off the support `S` is at most `α` times the mass on `S`.
`Δ_S` is `restrict S Δ` and `Δ_{Sᶜ}` is `restrict Sᶜ Δ` from `VecNorms`. -/
def reCone (S : Finset (Fin d)) (α : ℝ) : Set (EuclideanSpace ℝ (Fin d)) :=
  {Δ | l1Norm (restrict Sᶜ Δ) ≤ α * l1Norm (restrict S Δ)}

/-- A **family of confidence sets at confidence level `γ`**: the random set `S(X)` covers the
true parameter with probability at least `γ`, whatever the true parameter is. -/
def IsConfidenceFamily (P : Θ → Measure 𝓧) (S : 𝓧 → Set Θ) (γ : ℝ) : Prop :=
  ∀ θ, ENNReal.ofReal γ ≤ P θ {x | θ ∈ S x}

/-- A **critical function** (randomized test): measurable, `[0,1]`-valued. -/
def IsCriticalFn (φ : 𝓧 → ℝ) : Prop :=
  Measurable φ ∧ ∀ x, φ x ∈ Set.Icc (0 : ℝ) 1

/-- An **invariant set**: fixed by every element of the group. -/
def IsInvariantSet (G : Type*) [Group G] [MulAction G 𝓧] (A : Set 𝓧) : Prop :=
  ∀ g : G, (fun x : 𝓧 => g • x) ⁻¹' A = A

/-- **Invariant test**: unchanged along every orbit. -/
def IsInvariantTest (G : Type*) [Group G] [MulAction G 𝓧] (φ : 𝓧 → ℝ) : Prop :=
  ∀ (g : G) (x : 𝓧), φ (g • x) = φ x

/-- **Level-`α`** test on the null set `Θ₀`: power at most `α` there. -/
def IsLevel (P : Θ → Measure 𝓧) (Θ₀ : Set Θ) (φ : 𝓧 → ℝ) (α : ℝ) : Prop :=
  ∀ θ ∈ Θ₀, power P φ θ ≤ α

/-- **Similar test** on `ω`: power identically `α` there. -/
def IsSimilar (P : Θ → Measure 𝓧) (ω : Set Θ) (α : ℝ) (φ : 𝓧 → ℝ) : Prop :=
  ∀ θ ∈ ω, power P φ θ = α

/-- The sample space of a two-sample split: the `m`-element subsets of `Fin n`, i.e. the
possible first groups. Empty when `m > n`. -/
abbrev SubsetsOfCard (n m : ℕ) := {s : Finset (Fin n) // s.card = m}

/-- The **inverted family of confidence sets** of a family of acceptance regions:
`S(x) = {θ : x ∈ A θ}`, the parameter values not rejected on observing `x`. -/
def confidenceSet (A : Θ → Set 𝓧) (x : 𝓧) : Set Θ :=
  {θ | x ∈ A θ}

/-- The **constrained `L²` test class**: `[0,1]`-valued elements of `L²(μ)` satisfying the
linear (moment) side conditions `⟪gᵢ, f⟫ = cᵢ`. The index type is arbitrary. -/
def constrainedTestClassL2 (μ : Measure 𝓧) {ι : Type*} (g : ι → Lp ℝ 2 μ) (c : ι → ℝ) :
    Set (Lp ℝ 2 μ) :=
  testClassL2 μ ∩ {f | ∀ i, ⟪g i, f⟫_ℝ = c i}

/-- The set of discrepancies over measurable convex sets — the class the self-improving
induction runs on. -/
def convexDiscrepancySet (μ ν : Measure (EuclideanSpace ℝ (Fin k))) : Set ℝ :=
  {d : ℝ | ∃ B : Set (EuclideanSpace ℝ (Fin k)),
      MeasurableSet B ∧ Convex ℝ B ∧ d = |(μ B).toReal - (ν B).toReal|}

/-- The open `ε`-erosion of `B`: the points whose closed `ε`-ball lies in the interior of `B`.
It is open and convex, and its `ε`-thickening is contained in `B`. -/
def erosion (ε : ℝ) (B : Set (EuclideanSpace ℝ (Fin k))) : Set (EuclideanSpace ℝ (Fin k)) :=
  {x | Metric.closedBall x ε ⊆ interior B}

/-- The **invariant sets**: the measurable sets fixed by every element of the group. The
carrier of the invariant σ-algebra (see the carrier note in the file header). -/
def invariantSets (G 𝓧 : Type*) [Group G] [MeasurableSpace 𝓧] [MulAction G 𝓧] :
    Set (Set 𝓧) :=
  {A | MeasurableSet A ∧ IsInvariantSet G A}

/-- The **attainable-moment set**: the set of vectors `(∫φf₁dμ, …, ∫φf_mdμ)` obtained as
`φ` ranges over all critical functions. It is convex and closed (`convex_isClosed_momentSet`),
and the constraint vector being one of its inner points is the hypothesis under which
undetermined multipliers exist. For `m = 0` it is the one-point set `{()}`. -/
def momentSet {m : ℕ} (μ : Measure 𝓧) (f : Fin m → 𝓧 → ℝ) : Set (Fin m → ℝ) :=
  {u | ∃ φ, IsCriticalFn φ ∧ ∀ i, ∫ x, φ x * f i x ∂μ = u i}

/-- Reparametrization of the parameter of interest: `(θ, ϑ) ↦ (a₀θ + ⟪a, ϑ⟫, ϑ)`. -/
def reparamUT (a₀ : ℝ) (a : Ξ) : ℝ × Ξ → ℝ × Ξ :=
  fun p => (a₀ * p.1 + ⟪a, p.2⟫_ℝ, p.2)

entries.doc:
**The dominated-convergence step.** For each fixed lag `h ≠ 0` the inner frequency `2t₁h`
leaves every compact set as `|t₁| → ∞`, so the transform of the autocorrelation tends to `0`;
`‖g_h‖₁` dominates, and it is integrable in `h` because `∫∫|f(z + h)f(z)| = ‖f‖₁²`.

entries.source:
/-- The **`L²` test class**: the (a.e.) `[0,1]`-valued elements of `L²(μ)`. These are exactly
the critical functions of the testing theory, viewed in `L²`. -/
def testClassL2 (μ : Measure 𝓧) : Set (Lp ℝ 2 μ) :=
  {f | (0 : 𝓧 → ℝ) ≤ᵐ[μ] ⇑f ∧ ⇑f ≤ᵐ[μ] (1 : 𝓧 → ℝ)}

/-- The `s`-sparse Euclidean unit ball `S_d(s) = B₀(s) ∩ B₂(1) = {θ : ‖θ‖₀ ≤ s, ‖θ‖₂ ≤ 1}`
(Wainwright Eq. 15.40), the parameter set over which the sparse-regression minimax risk is taken. A
vector is `s`-sparse when at most `s` coordinates are nonzero. -/
def SparseBall (d s : ℕ) : Set (EuclideanSpace ℝ (Fin d)) :=
  {θ | (Finset.univ.filter fun i => θ i ≠ 0).card ≤ s ∧ ‖θ‖ ≤ 1}

/-- The event "the sample's true-coordinates are exactly `T`". -/
def evtSet {ι : Type*} (σ : ι → Ω → Bool) (T : Finset ι) : Set Ω :=
  ⋂ i, (σ i) ⁻¹' (if i ∈ T then ({true} : Set Bool) else {false})

/-- **(LP3)**: the kernel is bounded by `Kmax` and supported in `[−1, 1]`. -/
def KernelBoxed (K : ℝ → ℝ) (Kmax : ℝ) : Prop :=
  (∀ u, |K u| ≤ Kmax) ∧ ∀ u, u ∉ Set.Icc (-1 : ℝ) 1 → K u = 0

/-- Labeled data is **linearly separable** if some affine hyperplane separates it. -/
def LinearlySeparable {ι : Type*} (x : ι → E) (lab : ι → ℝ) : Prop :=
  ∃ (v : E) (c : ℝ), SeparatesData v c x lab

/-- The **normalized feasible set** of the maximal margin problem: normal vectors `v`
admitting an offset `c` with all data constraints `λ i (⟪x i, v⟫ − c) ≥ 1`. -/
def marginFeasible (x : Fin n → E) (lab : Fin n → ℝ) : Set E :=
  {v : E | ∃ c : ℝ, ∀ i, 1 ≤ lab i * (⟪x i, v⟫ - c)}

/-- The **adjoint of a symbol**: `S*(y, x) = conj (S x y)` — the continuous analogue of
the conjugate transpose. -/
def symbolAdjoint (S : X → Y → 𝕜) : Y → X → 𝕜 := fun y x => conj (S x y)

/-- The subdifferential `∂f(x)`: the set of all subgradients of `f` at `x`
(Lu-BDA §12.2, Definition 12.3 (Subgradient)). May be empty for nonconvex `f`;
for convex `f` it is nonempty. -/
def subdifferential (f : E → ℝ) (x : E) : Set E :=
  {g | IsSubgradient f x g}

entries.doc:
The subdifferential `∂f(x)`: the set of all subgradients of `f` at `x`
(Lu-BDA §12.2, Definition 12.3 (Subgradient)). May be empty for nonconvex `f`;
for convex `f` it is nonempty.

entries.source:
/-- The **natural parameter set** `{η | ∫ e^{⟨η,T⟩} dν < ∞}` — the largest set on which
the family is defined. Convexity is proved in `ExponentialFamily.Basic`. -/
def natSet : Set V :=
  {η : V | Integrable (fun x => Real.exp ⟪η, E.stat x⟫_ℝ) E.base}

/-- The **`f`-weighted natural parameter set**: the natural parameters at which the weighted
integrand `|f|·e^{⟨η, T⟩}` is integrable against the reference measure. For `f ≡ 1` this is
`ExpFamily.natSet`. Like the natural parameter set it is a convex subset of `V`. -/
def weightedNatSet (E : ExpFamily 𝓧 V) (f : 𝓧 → ℝ) : Set V :=
  {η : V | Integrable (fun x => |f x| * Real.exp ⟪η, E.stat x⟫_ℝ) E.base}

/-- A statistic `V` is **ancillary**: its law is the same under every parameter. -/
def IsAncillary (P : Θ → Measure 𝓧) (V : 𝓧 → S) : Prop :=
  ∀ θ θ', (P θ).map V = (P θ').map V

/-- A statistic `T` is **boundedly complete** for `P` when the family of its laws is. -/
def IsBoundedlyCompleteStat (P : Θ → Measure 𝓧) (T : 𝓧 → S) : Prop :=
  IsBoundedlyCompleteFamily fun θ => (P θ).map T

/-- A statistic `T` is **complete** for the model `P` when the family of its laws is. -/
def IsCompleteStat (P : Θ → Measure 𝓧) (T : 𝓧 → S) : Prop :=
  IsCompleteFamily fun θ => (P θ).map T

/-- **Equivariant estimator**: intertwines the sample- and decision-space actions. -/
def IsEquivariant (δ : 𝓧 → D) : Prop :=
  ∀ (g : G) (x : 𝓧), δ (g • x) = g • δ x

/-- **Location-equivariant estimator**: `δ(x + a·𝟙) = δ(x) + a`. -/
def IsLocEquivariant (δ : (Fin n → ℝ) → ℝ) : Prop :=
  ∀ (a : ℝ) (x : Fin n → ℝ), δ (x + a • (1 : Fin n → ℝ)) = δ x + a

/-- **Location-invariant function** (of the data): `u(x + a·𝟙) = u(x)`. -/
def IsLocInvariant (u : (Fin n → ℝ) → ℝ) : Prop :=
  ∀ (a : ℝ) (x : Fin n → ℝ), u (x + a • (1 : Fin n → ℝ)) = u x

/-- `δ` is an **unbiased estimator** of `g`: `E_θ δ = g θ` for every `θ`. -/
def IsUnbiased (P : Θ → Measure 𝓧) (g : Θ → ℝ) (δ : 𝓧 → ℝ) : Prop :=
  ∀ θ, ∫ x, δ x ∂(P θ) = g θ

/-- `U` is an **unbiased estimator of zero**. -/
def IsUnbiasedZero (P : Θ → Measure 𝓧) (U : 𝓧 → ℝ) : Prop :=
  IsUnbiased P (fun _ => 0) U

/-- The estimator class `Δ`: square-integrable under every member of the model. -/
def MemEstL2 (P : Θ → Measure 𝓧) (δ : 𝓧 → ℝ) : Prop :=
  ∀ θ, MemLp δ 2 (P θ)

/-- The **signal block** `(Y₁, …, Y_s)`: the first `s` coordinates of the observation. -/
def canonicalHead (y : EuclideanSpace ℝ (Fin (s + m))) : Fin s → ℝ :=
  fun i => y (Fin.castAdd m i)

/-- The **residual sum of squares** `S² = ∑_{j=1}^{m} Y_{s+j}²` of the canonical model. -/
def canonicalRSS (y : EuclideanSpace ℝ (Fin (s + m))) : ℝ :=
  ∑ j : Fin m, y (Fin.natAdd s j) ^ 2

/-- `m` replacements break the dispersion estimator: explosion or implosion. -/
def DispersionBreaksUnder (S : (Fin n → ℝ) → ℝ) (x : Fin n → ℝ) (m : ℕ) : Prop :=
  ¬DispersionResists S x m

/-- **The check (pinball) loss** `ρ_α(x) = max(αx, (α−1)x)` (`MMY §4.8`, opening
display): `αx` for `x ≥ 0`, `(α−1)x = −(1−α)x` for `x < 0`. -/
def checkLoss (α x : ℝ) : ℝ := max (α * x) ((α - 1) * x)

/-- The **gross-error (contamination) neighbourhood** of `P` at level `ε`
(`MMY §3.3`, eq. (3.3)): all mixtures `(1-ε)P + εQ` with `Q` a probability measure. -/
def grossErrorNbhd (P : Measure Ω) (ε : ℝ) : Set (Measure Ω) :=
  {R | ∃ Q : Measure Ω, IsProbabilityMeasure Q ∧ R = contaminate P Q ε}

entries.doc:
The best-in-class risk is a lower bound: `bestRisk ≤ risk g` for `g ∈ 𝓗`,
provided the risk image is bounded below (LEAN-ONLY `sInf` regularity;
nonnegative losses give `BddBelow` via `risk_nonneg`).

entries.source:
/-- The pair-space error set of a predictor: `{(x,y) | h(x) ≠ y}` — the 0–1
loss of `h` is its indicator (SSBD Eq. (3.1)). -/
def errSet (h : X → Bool) : Set (X × Bool) :=
  {p | h p.1 ≠ p.2}

entries.doc:
**SSBD Theorem 26.5, part 1**: with probability `≥ 1 − δ`, simultaneously
for every `k ∈ K`,
`L_D(F k) − L_S(F k) ≤ 2 E_{S'∼Dⁿ} R(F∘S') + c √(2 ln(2/δ)/n)`.

entries.source:
/-- The `±1` vector of a Boolean sign pattern: `true ↦ 1`, `false ↦ -1`. -/
def signOf (σ : Fin n → Bool) : Fin n → ℝ :=
  fun i => if σ i then 1 else -1

/-- **Uniform positivity / overlap**: the response probability is bounded below by `δ`. -/
def HasPositivity (ρ' : Kernel 𝓧 Bool) (δ : ℝ) : Prop :=
  ∀ x, δ ≤ propensity ρ' x

entries.doc:
**C3, the Horvitz–Thompson identity under MAR** (`HT52`; Robins–Rotnitzky–Zhao 1994 §2;
`vdV §25.5.3` Example 25.43): under a MAR mechanism with uniform positivity, the
inverse-propensity-weighted observed outcome recovers the full-data outcome mean.

entries.source:
/-- **Diagonal uniqueness**: `Ψ` is diagonal, i.e. the specific factors are uncorrelated
across coordinates — `BKM`'s conditional-independence assumption (Eq. (1.9), §1.4;
Eq. (3.1)). -/
def HasDiagonalUniqueness (P : FactorParams p q) : Prop :=
  Matrix.IsDiag P.uniqueCov

entries.doc:
**Diagonal uniqueness**: `Ψ` is diagonal, i.e. the specific factors are uncorrelated
across coordinates — `BKM`'s conditional-independence assumption (Eq. (1.9), §1.4;
Eq. (3.1)).

entries.source:
theorem RealizesFactorParams.covMatrix_error {P : FactorParams p q}
    {F : Measure (EuclideanSpace ℝ (Fin q))} {E : Measure (EuclideanSpace ℝ (Fin p))}
    (h : RealizesFactorParams P F E) : covMatrix E = P.uniqueCov := h.2.2.2

theorem RealizesFactorParams.covMatrix_latent {P : FactorParams p q}
    {F : Measure (EuclideanSpace ℝ (Fin q))} {E : Measure (EuclideanSpace ℝ (Fin p))}
    (h : RealizesFactorParams P F E) : covMatrix F = P.factorCov := h.2.2.1

theorem RealizesFactorParams.meanVec_error {P : FactorParams p q}
    {F : Measure (EuclideanSpace ℝ (Fin q))} {E : Measure (EuclideanSpace ℝ (Fin p))}
    (h : RealizesFactorParams P F E) : meanVec E = 0 := h.2.1

theorem RealizesFactorParams.meanVec_latent {P : FactorParams p q}
    {F : Measure (EuclideanSpace ℝ (Fin q))} {E : Measure (EuclideanSpace ℝ (Fin p))}
    (h : RealizesFactorParams P F E) : meanVec F = 0 := h.1

/-- Every law compatible with the constraint is a probability measure. -/
def FibersProbability (C : Θ → Set (Measure 𝓧)) : Prop :=
  ∀ θ, ∀ Q ∈ C θ, IsProbabilityMeasure Q

/-- A chain read from its far end. Each step keeps its arrow and changes its traversal
direction. -/
def reverse {u w : V} (c : Chain r u w) : Chain r w u := c.reverseAux (nil u)

entries.doc:
The **random censorship model**: the observed-data law under independent censoring —
the product joint `(T, C) ∼ μT ⊗ μC` pushed through `censorObserve` (ABGK §III.2;
Breslow–Crowley 1974). Independence is structural here, not a hypothesis.

entries.source:
/-- The **hazard jump** `ΔΛ(t) = Λ{t}` (ABGK §II.1: `ΔΛ = ΔF/S(−)` at atoms). -/
noncomputable def cumHazardJump (μ : Measure ℝ) (t : ℝ) : ℝ≥0∞ :=
  cumHazard μ {t}

entries.doc:
**`naJump` is the genuine jump of `nelsonAalen`** at an event time: the estimator at `s`
is its strict-past partial sum plus the increment (the content behind `KM = ∏(1 − ΔNA)`;
ABGK §IV.1 vs §IV.3).

entries.source:
/-- The `k = 1` marked carrier collapses to the censoring carrier. -/
def toBoolObs : ℝ × Option (Fin 1) → ℝ × Bool :=
  fun p => (p.1, p.2.isSome)

/-- A fully specified model as a constraint model: each fiber is the singleton of the
assigned law. -/
def singletonFibers (P : Θ → Measure 𝓧) : Θ → Set (Measure 𝓧) :=
  fun θ => {P θ}

/-- **α-mixing** (strong mixing) process (FY Definition 2.11): `α(n) → 0`. -/
def IsAlphaMixing (X : ℤ → Ω → ℝ) (μ : Measure Ω) : Prop :=
  Tendsto (fun n : ℕ => alphaCoeff X μ n) atTop (𝓝 0)

/-- **β-mixing** (absolutely regular) process (FY Definition 2.11): `β(n) → 0`. -/
def IsBetaMixing (X : ℤ → Ω → ℝ) (μ : Measure Ω) : Prop :=
  Tendsto (fun n : ℕ => betaCoeff X μ n) atTop (𝓝 0)

/-- **Ergodic kernel** (FY Definition 2.4 with `ρ = 1`). -/
def IsErgodicKernel (κ : Kernel S S) (F : Measure S) : Prop :=
  IsErgodicWithRate κ F 1

/-- **Geometrically ergodic kernel** (FY Definition 2.4 with some `ρ < 1`). -/
def IsGeometricallyErgodic (κ : Kernel S S) (F : Measure S) : Prop :=
  ∃ ρ : ℝ≥0∞, ρ < 1 ∧ IsErgodicWithRate κ F ρ

/-- **φ-mixing** process (FY Definition 2.11): `φ(n) → 0`. -/
def IsPhiMixing (X : ℤ → Ω → ℝ) (μ : Measure Ω) : Prop :=
  Tendsto (fun n : ℕ => phiCoeff X μ n) atTop (𝓝 0)

/-- **ψ-mixing** process (FY Definition 2.11): `ψ(n) → 0`. -/
def IsPsiMixing (X : ℤ → Ω → ℝ) (μ : Measure Ω) : Prop :=
  Tendsto (fun n : ℕ => psiCoeff X μ n) atTop (𝓝 0)

/-- **ρ-mixing** process (FY Definition 2.11): `ρ(n) → 0`. -/
def IsRhoMixing (X : ℤ → Ω → ℝ) (μ : Measure Ω) : Prop :=
  Tendsto (fun n : ℕ => rhoCoeff X μ n) atTop (𝓝 0)

/-- The **data-adapted admissible set** at variance floor `κ`: the parameters `(c₀, b)` at
which the truncated conditional variance the ARCH criterion divides by stays `≥ κ`
throughout the criterion's own index range `Ico ν T`. -/
def archAdmissible (κ : ℝ) {p T : ℕ} (x : Fin T → ℝ) (ν : ℕ) : Set (ℝ × (Fin p → ℝ)) :=
  {θ | ∀ t ∈ Finset.Ico ν T, κ ≤ garchTruncVol θ.1 θ.2 (Fin.elim0 : Fin 0 → ℝ) θ.1 x t}

/-- The **null slice** `{b = 0}` of a search region — the restricted parameter space of
`H₀ : b₁ = ⋯ = b_p = 0`. -/
def archNullSlice {p : ℕ} (K : Set (ℝ × (Fin p → ℝ))) : Set (ℝ × (Fin p → ℝ)) :=
  K ∩ {θ | θ.2 = fun _ => (0 : ℝ)}

theorem lyapV_le {θ : ℝ} {x : Fin (p + 1) → ℝ} {b : ℝ}
    (h : ∀ i : Fin (p + 1), θ ^ (i : ℕ) * |x i| ≤ b) : lyapV θ x ≤ b :=
  ciSup_le h

/-- The row sums `S_n = Σ_{i<k_n} X_{n,i}`. -/
def mdsRowSum (k : ℕ → ℕ) (X : (n : ℕ) → Fin (k n) → Ω → ℝ) (n : ℕ) (ω : Ω) : ℝ :=
  ∑ i, X n i ω
